        effects_clip = base_clip.transform(frame_effect_filter)
        
                                # Phase 2-B: MoviePy 100% Universal Guaranteed Subtitle Top Layer
        def apply_subtitle_to_frame(frame_in, t_val):
            frame_out = frame_in.copy()
